def citta(lang):
    """tuple nello stesso formato di CITTA nei file dati/traduzioni: (nome, slug, area, hero, p1, p2, zone)"""
    out = []
    for nome, slug, area, hero, p1, p2, zone in NUOVE_IT:
        if lang != 'it':
            area, p1, p2 = TR[lang][slug]
        out.append((nome, slug, area, hero, p1, p2, zone))
    return out
